   323→        return NextResponse.json(
   324→          {
   325→            success: false,
   326→            error: 'INVALID_REFERENCE_IMAGE_FORMAT',
   327→            message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
   328→          },
   329→          { status: 400 }
   330→        );
   331→      }
   332→    }
   333→
   334→    // Validate that try-on and try-on-dual generation require a reference image
   335→    if ((generationType === 'try-on' || generationType === 'try-on-dual') && !referenceImage) {
