   423→          if (generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') {
   424→            console.log('[API] Applying background removal for', generationType);
   425→            const bgRemovalSuccess = await removeBackgroundFromFile(filePath, filePath);
   426→
   427→            if (bgRemovalSuccess) {
