   444→          console.warn('[API] Continuing without imageUrl - base64 still available');
   445→        }
   446→      }
   447→
   448→      return NextResponse.json(result, {
   449→        status: 200,
   450→        headers: {
   451→          'Cache-Control': 'no-cache, no-store, must-revalidate',
   452→        },
   453→      });
   454→    } else {
   455→      // Determine status code based on error type
